${{
  var ask = function (title, msg, def) {
    try {
      var box = { value: def || "" };
      var ok = Services.prompt.prompt(null, title, msg, box, null, {});
      return ok ? box.value : "";
    } catch (e) {
      try {
        return Zotero.getMainWindow().prompt(msg, def || "") || "";
      } catch (e2) {
        return "";
      }
    }
  };

  var clean = function (s) {
    return (s || "").replace(/\s+/g, " ").trim();
  };

  var scope = function (item) {
    var lib = Zotero.Libraries.get(item.libraryID);
    return lib && lib.isGroup ? "groups/" + lib.id : "library";
  };

  // Full reference for a source, in APA style. Change the style id below to use
  // another installed citation style.
  var citeFormat = "bibliography=http://www.zotero.org/styles/apa";
  var citeCache = {};
  var mdEscape = function (s) {
    return (s || "").replace(/([\\\x60*_\[\]<>])/g, "\\$1");
  };
  var fullCite = function (item, fallback) {
    var target = item;
    try {
      if (item.isAttachment() && item.parentItemID) {
        target = Zotero.Items.get(item.parentItemID) || item;
      }
    } catch (e) {
      target = item;
    }
    if (citeCache[target.id]) return citeCache[target.id];
    var text = "";
    try {
      if (target.isRegularItem()) {
        var res = Zotero.QuickCopy.getContentFromItems([target], citeFormat);
        text = ((res && res.text) || "").replace(/\s+/g, " ").trim();
      }
    } catch (e) {
      text = "";
    }
    if (!text) text = fallback;
    citeCache[target.id] = text;
    return text;
  };

  var describe = function (item) {
    var creators = item.getCreators();
    var author = "No author";
    if (creators.length === 1) {
      author = creators[0].lastName || creators[0].firstName || "No author";
    } else if (creators.length > 1) {
      author = (creators[0].lastName || creators[0].firstName) + " et al.";
    }
    var date = item.getField("date") || "";
    var m = date.match(/\d{4}/);
    var year = m ? m[0] : "n.d.";
    var outlet =
      item.getField("publicationTitle") ||
      item.getField("websiteTitle") ||
      item.getField("publisher") ||
      item.getField("blogTitle") ||
      "";
    return {
      label: author + " (" + year + ")",
      title: item.getField("title") || "Untitled",
      outlet: outlet,
      link: "zotero://select/" + scope(item) + "/items/" + item.key,
      cite: fullCite(
        item,
        author + " (" + year + "). " + (item.getField("title") || "Untitled") +
          (outlet ? ". " + outlet : "") + "."
      )
    };
  };

  var harvest = async function (item) {
    var source = describe(item);
    var attIDs = item.isAttachment() ? [item.id] : item.getAttachments();
    var out = [];
    var skipped = [];
    for (var i = 0; i < attIDs.length; i++) {
      var att = Zotero.Items.get(attIDs[i]);
      if (!att) {
        try {
          att = await Zotero.Items.getAsync(attIDs[i]);
        } catch (e) {
          continue;
        }
      }
      if (!att) continue;
      var anns = [];
      try {
        anns = att.getAnnotations() || [];
      } catch (e) {
        anns = [];
      }
      for (var j = 0; j < anns.length; j++) {
        var ann = anns[j];
        var text = clean(ann.annotationText);
        var memo = clean(ann.annotationComment);
        var codes = ann
          .getTags()
          .map(function (t) { return t.tag; })
          .filter(function (t) { return t && t.indexOf("zotero://") !== 0; });
        if (!codes.length) continue;
        // Coded, but nothing to quote. Usually an image or area annotation.
        // Record it so the report can say so instead of dropping it silently.
        if (!text && !memo) {
          skipped.push({ codes: codes, source: source });
          continue;
        }
        out.push({
          text: text,
          memo: memo,
          codes: codes,
          source: source,
          page: ann.annotationPageLabel || "",
          link:
            "zotero://open/" + scope(item) + "/items/" +
            att.key + "?annotation=" + ann.key
        });
      }
    }
    return { source: source, extracts: out, skipped: skipped };
  };

  var renderExtract = function (e, showCodes) {
    var lines = [];
    lines.push(e.text ? "> " + e.text : "> *(no highlighted text, memo only)*");
    lines.push("> ");
    var cite = "> **Source:** " + mdEscape(e.source.cite);
    if (e.page) cite += " (p. " + e.page + ")";
    cite += " [\\[Open highlight\\]](" + e.link + ")";
    lines.push(cite);
    if (e.memo) {
      lines.push("> ");
      lines.push("> **Memo:** " + e.memo);
    }
    if (showCodes && e.codes.length > 1) {
      lines.push("> ");
      lines.push("> *Also coded:* " + e.codes.join(", "));
    }
    return lines.join("\n");
  };

  var findCollection = function (libraryID, name) {
    var all = [];
    try {
      all = Zotero.Collections.getByLibrary(libraryID, true) || [];
    } catch (e) {
      all = [];
    }
    var want = name.toLowerCase();
    for (var i = 0; i < all.length; i++) {
      if ((all[i].name || "").toLowerCase() === want) return all[i];
    }
    for (var k = 0; k < all.length; k++) {
      if ((all[k].name || "").toLowerCase().indexOf(want) !== -1) return all[k];
    }
    return null;
  };

  // The sources are the items this template was run on (kept in the block
  // header, so a refresh scans the same items).

  // ---------- harvest ----------
  var byCode = {};
  var uncoded = [];
  var skippedAll = [];
  var codedSources = 0;
  var sourceList = [];
  for (var n = 0; n < items.length; n++) {
    var res = await harvest(items[n]);
    sourceList.push(res.source);
    for (var s = 0; s < res.skipped.length; s++) skippedAll.push(res.skipped[s]);
    if (!res.extracts.length) {
      uncoded.push(res.source);
      continue;
    }
    codedSources += 1;
    for (var x = 0; x < res.extracts.length; x++) {
      var ex = res.extracts[x];
      for (var y = 0; y < ex.codes.length; y++) {
        var c = ex.codes[y];
        if (!byCode[c]) byCode[c] = [];
        byCode[c].push(ex);
      }
    }
  }

  // ---------- render ----------
  var codes = Object.keys(byCode).sort(function (a, b) {
    return a.toLowerCase().localeCompare(b.toLowerCase());
  });
  var countSources = function (list) {
    var s = new Set(list.map(function (e) { return e.source.link; }));
    return s.size;
  };
  var scannedLabel = items.length + " selected item(s)";
  var out = [];
  var exCodes = {};
  codes.forEach(function (key) {
    byCode[key].forEach(function (e) {
      if (!exCodes[e.link]) exCodes[e.link] = [];
      if (exCodes[e.link].indexOf(key) === -1) exCodes[e.link].push(key);
    });
  });
  var links = Object.keys(exCodes);
  var pairKey = function (a, b) { return a < b ? a + "\u0001" + b : b + "\u0001" + a; };
  var pairCount = {};
  var multi = 0;
  links.forEach(function (link) {
    var list = exCodes[link];
    if (list.length > 1) multi += 1;
    for (var a = 0; a < list.length; a++) {
      for (var b = a + 1; b < list.length; b++) {
        var k = pairKey(list[a], list[b]);
        pairCount[k] = (pairCount[k] || 0) + 1;
      }
    }
  });
  var cell = function (text) { return String(text).replace(/\|/g, "\\|"); };

  out.push("<span style=\"color: #e03131\"><em><strong>Everything from here down to the line at the bottom is regenerated every time you refresh this note.</strong> Do not type inside it. Write any notes of your own below that line, or a refresh will erase them.</em></span>");
  out.push("");
  out.push("## Scope");
  out.push("");
  out.push(
    "- **Built from " + codes.length + " code(s), " + links.length + " extract(s), " +
    codedSources + " source(s), out of " + items.length + " sources scanned.**"
  );
  out.push("- **Extracts with more than one code:** " + multi);
  out.push("- **Scanned:** " + scannedLabel);
  var shown = sourceList.slice(0, 50);
  for (var s2 = 0; s2 < shown.length; s2++) {
    out.push("  - " + mdEscape(shown[s2].cite));
  }
  if (sourceList.length > shown.length) {
    out.push("  - and " + (sourceList.length - shown.length) + " more");
  }
  out.push("- **Generated:** " + new Date().toLocaleString());
  out.push("");

  if (skippedAll.length) {
    out.push("> **" + skippedAll.length + " coded annotation(s) not counted.** They have neither highlighted text nor a memo. These are usually image or area annotations. Add a memo to the annotation if you want it counted.");
    out.push("");
  }

  out.push("## Code matrix");
  out.push("");
  if (!codes.length) {
    out.push("> No tagged highlights were found. Highlight a passage in the Zotero reader, then add a tag to that highlight in the annotation sidebar. A highlight with no tag is not a code.");
    return out.join("\n");
  }
  out.push("*Each cell counts the extracts (highlights) that carry both codes. A dash marks where a code meets itself, and 0 means the two codes never appear on the same extract.*");
  out.push("");
  out.push("| | " + codes.map(cell).join(" | ") + " |");
  out.push("| :-- |" + codes.map(function () { return " :-: |"; }).join(""));
  for (var r = 0; r < codes.length; r++) {
    var row = "| **" + cell(codes[r]) + "** |";
    for (var c2 = 0; c2 < codes.length; c2++) {
      if (r === c2) {
        row += " - |";
      } else {
        var count = pairCount[pairKey(codes[r], codes[c2])] || 0;
        row += " " + count + " |";
      }
    }
    out.push(row);
  }
  out.push("");
  out.push("## Pairs that co-occur");
  out.push("");
  var pairs = Object.keys(pairCount).map(function (k) {
    var parts = k.split("\u0001");
    return { a: parts[0], b: parts[1], n: pairCount[k] };
  }).sort(function (x, y) {
    return y.n - x.n || (x.a + x.b).toLowerCase().localeCompare((y.a + y.b).toLowerCase());
  });
  if (!pairs.length) {
    out.push("*No extract carries more than one code, so no codes co-occur yet.*");
  }
  for (var p3 = 0; p3 < pairs.length; p3++) {
    out.push("- **" + pairs[p3].a + "** + **" + pairs[p3].b + "**: " + pairs[p3].n + " extract(s)");
  }
  return out.join("\n");
}}$
